@import '@fontsource-variable/geist';
@import '@fontsource-variable/geist-mono';
@import '@fontsource/instrument-serif';
@import 'tailwindcss';

:root {
  color-scheme: light dark;

  --bg: oklch(0.975 0.006 85);
  --surface: oklch(0.998 0.002 85);
  --surface-2: oklch(0.958 0.006 85);
  --surface-3: oklch(0.925 0.007 85);
  --line: oklch(0.91 0.007 85);
  --line-strong: oklch(0.84 0.009 85);
  --ink: oklch(0.2 0.012 65);
  --ink-2: oklch(0.43 0.012 65);
  --ink-3: oklch(0.6 0.01 65);
  --ink-4: oklch(0.72 0.008 65);

  --overlap: oklch(0.84 0.19 146);
  --overlap-edge: oklch(0.72 0.19 148);
  --overlap-ink: oklch(0.27 0.08 150);
  --now: oklch(0.63 0.22 27);
  --warn: oklch(0.76 0.15 72);
  --warn-soft: oklch(0.965 0.04 88);
  --warn-ink: oklch(0.43 0.1 60);

  --hatch: color-mix(in oklab, var(--ink) 9%, transparent);
  --shadow-card: 0 1px 0 color-mix(in oklab, var(--ink) 4%, transparent),
    0 12px 32px -18px color-mix(in oklab, var(--ink) 22%, transparent);
  --shadow-pop: 0 1px 2px color-mix(in oklab, var(--ink) 8%, transparent),
    0 24px 48px -16px color-mix(in oklab, var(--ink) 28%, transparent);

  --grid-label: 9rem;
  --grid-action: 1.75rem;
  --grid-gap: 2px;
}

@media (min-width: 1024px) {
  :root {
    --grid-label: 12.5rem;
    --grid-action: 2rem;
    --grid-gap: 3px;
  }
}

@media (min-width: 1280px) {
  :root {
    --grid-label: 15rem;
  }
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: oklch(0.165 0.008 255);
    --surface: oklch(0.2 0.009 255);
    --surface-2: oklch(0.245 0.01 255);
    --surface-3: oklch(0.29 0.011 255);
    --line: oklch(0.285 0.01 255);
    --line-strong: oklch(0.36 0.012 255);
    --ink: oklch(0.96 0.004 255);
    --ink-2: oklch(0.77 0.008 255);
    --ink-3: oklch(0.6 0.01 255);
    --ink-4: oklch(0.47 0.01 255);

    --overlap: oklch(0.8 0.19 146);
    --overlap-edge: oklch(0.88 0.17 146);
    --overlap-ink: oklch(0.2 0.06 150);
    --now: oklch(0.7 0.19 27);
    --warn: oklch(0.78 0.14 75);
    --warn-soft: oklch(0.26 0.04 75);
    --warn-ink: oklch(0.88 0.1 85);

    --hatch: color-mix(in oklab, var(--ink) 7%, transparent);
    --shadow-card: 0 1px 0 color-mix(in oklab, white 4%, transparent) inset, 0 16px 40px -24px black;
    --shadow-pop: 0 1px 0 color-mix(in oklab, white 6%, transparent) inset, 0 24px 56px -12px black;
  }
}

@theme inline {
  --color-bg: var(--bg);
  --color-surface: var(--surface);
  --color-surface-2: var(--surface-2);
  --color-surface-3: var(--surface-3);
  --color-line: var(--line);
  --color-line-strong: var(--line-strong);
  --color-ink: var(--ink);
  --color-ink-2: var(--ink-2);
  --color-ink-3: var(--ink-3);
  --color-ink-4: var(--ink-4);
  --color-overlap: var(--overlap);
  --color-overlap-edge: var(--overlap-edge);
  --color-overlap-ink: var(--overlap-ink);
  --color-now: var(--now);
  --color-warn: var(--warn);
  --color-warn-soft: var(--warn-soft);
  --color-warn-ink: var(--warn-ink);

  --font-sans: 'Geist Variable', ui-sans-serif, system-ui, sans-serif;
  --font-mono: 'Geist Mono Variable', ui-monospace, 'SF Mono', Menlo, monospace;
  --font-display: 'Instrument Serif', ui-serif, Georgia, serif;

  --shadow-card: var(--shadow-card);
  --shadow-pop: var(--shadow-pop);

  --animate-pop-in: pop-in 160ms cubic-bezier(0.2, 0.9, 0.3, 1);
  --animate-pop-out: pop-out 100ms ease-in forwards;

  @keyframes pop-in {
    from {
      opacity: 0;
      transform: translateY(-4px) scale(0.98);
    }
  }
  @keyframes pop-out {
    to {
      opacity: 0;
      transform: translateY(-2px) scale(0.99);
    }
  }
}

@layer base {
  html {
    background: var(--bg);
    -webkit-text-size-adjust: 100%;
    text-rendering: optimizeLegibility;
  }

  body {
    min-height: 100dvh;
    color: var(--ink);
    font-family: var(--font-sans);
    font-feature-settings: 'ss01', 'cv11';
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    background:
      radial-gradient(60rem 28rem at 12% -8%, color-mix(in oklab, var(--overlap) 13%, transparent), transparent 70%),
      radial-gradient(50rem 24rem at 100% 0%, color-mix(in oklab, var(--ink) 4%, transparent), transparent 70%),
      var(--bg);
    background-repeat: no-repeat;
  }

  ::selection {
    background: color-mix(in oklab, var(--overlap) 55%, transparent);
    color: var(--ink);
  }

  :focus-visible {
    outline: 2px solid var(--ink);
    outline-offset: 2px;
  }

  button:not(:disabled) {
    cursor: pointer;
  }
}

@layer components {
  /* Shared by the header, rows and overlays of the desktop grid so every column lines up. */
  .grid-hours {
    display: grid;
    grid-template-columns: var(--grid-label) repeat(24, minmax(0, 1fr)) var(--grid-action);
    column-gap: var(--grid-gap);
  }

  [cmdk-group-heading] {
    padding: 0.625rem 0.625rem 0.25rem;
    font-size: 0.6875rem;
    font-weight: 600;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: var(--ink-3);
  }

  [cmdk-group][hidden] {
    display: none;
  }
}

@utility card {
  border: 1px solid var(--line);
  border-radius: 1.25rem;
  background: var(--surface);
  box-shadow: var(--shadow-card);
}

@utility popover {
  border: 1px solid var(--line);
  border-radius: 1rem;
  background: var(--surface);
  box-shadow: var(--shadow-pop);
  transform-origin: var(--radix-popover-content-transform-origin);
  z-index: 50;

  &[data-state='open'] {
    animation: var(--animate-pop-in);
  }
  &[data-state='closed'] {
    animation: var(--animate-pop-out);
  }
}

@utility bg-hatch {
  background-image: repeating-linear-gradient(-45deg, var(--hatch) 0 1px, transparent 1px 5px);
}

