  }
}

@theme inline {
  --color-bg: var(--bg);
  --color-surface: var(--surface);
  --color-surface-2: var(--surface-2);
  --color-surface-3: var(--surface-3);
  --color-line: var(--line);
  --color-line-strong: var(--line-strong);
  --color-ink: var(--ink);
  --color-ink-2: var(--ink-2);
  --color-ink-3: var(--ink-3);
  --color-ink-4: var(--ink-4);
  --color-overlap: var(--overlap);
  --color-overlap-edge: var(--overlap-edge);
  --color-overlap-ink: var(--overlap-ink);
  --color-now: var(--now);
  --color-warn: var(--warn);
  --color-warn-soft: var(--warn-soft);
  --color-warn-ink: var(--warn-ink);

  --font-sans: 'Geist Variable', ui-sans-serif, system-ui, sans-serif;
  --font-mono: 'Geist Mono Variable', ui-monospace, 'SF Mono', Menlo, monospace;
  --font-display: 'Instrument Serif', ui-serif, Georgia, serif;
}

@keyframes pop-in {
  from {
    opacity: 0;
    transform: translateY(-4px) scale(0.98);
  }
}

@keyframes pop-out {
  to {
    opacity: 0;
    transform: translateY(-2px) scale(0.99);
  }
}

@layer base {
  html {
    background: var(--bg);
    -webkit-text-size-adjust: 100%;
    text-rendering: optimizeLegibility;
  }

  body {
    min-height: 100dvh;
    color: var(--ink);
    font-family: var(--font-sans);
    font-feature-settings: 'ss01', 'cv11';
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    background:
      radial-gradient(60rem 28rem at 12% -8%, color-mix(in oklab, var(--overlap) 13%, transparent), transparent 70%),
      radial-gradient(50rem 24rem at 100% 0%, color-mix(in oklab, var(--ink) 4%, transparent), transparent 70%),
      var(--bg);
    background-repeat: no-repeat;
  }

