    outline: 2px solid var(--ink);
    outline-offset: 2px;
  }

  button:not(:disabled) {
    cursor: pointer;
  }
}

@layer components {
  /* Shared by the header, rows and overlays of the desktop grid so every column lines up. */
  .grid-hours {
    display: grid;
    grid-template-columns: var(--grid-label) repeat(24, minmax(0, 1fr)) var(--grid-action);
    column-gap: var(--grid-gap);
  }

  [cmdk-group-heading] {
    padding: 0.625rem 0.625rem 0.25rem;
    font-size: 0.6875rem;
    font-weight: 600;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: var(--ink-3);
  }

  [cmdk-group][hidden] {
    display: none;
  }
}

@utility card {
  border: 1px solid var(--line);
  border-radius: 1.25rem;
  background: var(--surface);
  box-shadow: var(--elev-card);
}

@utility popover {
  border: 1px solid var(--line);
  border-radius: 1rem;
  background: var(--surface);
  box-shadow: var(--elev-pop);
  transform-origin: var(--radix-popover-content-transform-origin);
  z-index: 50;

  &[data-state='open'] {
    animation: pop-in 160ms cubic-bezier(0.2, 0.9, 0.3, 1);
  }
  &[data-state='closed'] {
    animation: pop-out 100ms ease-in forwards;
  }
}

@utility bg-hatch {
  background-image: repeating-linear-gradient(-45deg, var(--hatch) 0 1px, transparent 1px 5px);
}

