import { memo } from 'react'
import type { CellState, Slot } from '../../domain/schedule'
import { clockParts, formatClock, WEEKDAYS, type TimeFormat } from '../../domain/time'
import { cn } from '../../lib/cn'

const STATE_STYLES: Record<CellState, string> = {
  overlap: 'bg-overlap font-bold text-overlap-ink shadow-[inset_0_0_0_1px_var(--overlap-edge)]',
  awake: 'bg-surface-2 font-medium text-ink-2 shadow-[inset_0_0_0_1px_var(--line)]',
  asleep: 'bg-hatch font-normal text-ink-4',
}

const STATE_LABEL: Record<CellState, string> = {
  overlap: 'awake, overlap',
  awake: 'awake',
  asleep: 'asleep',
}

interface HourCellProps {
  cityName: string
  slot: Slot
  state: CellState
  /** Local weekday for this slot (0 = Sunday). */
  weekday: number
  format: TimeFormat
  /** `row`: desktop, cities as rows. `column`: mobile, cities as columns. */
  variant: 'row' | 'column'
}

export const HourCell = memo(function HourCell({ cityName, slot, state, weekday, format, variant }: HourCellProps) {
  const { hour, minute, period } = clockParts(slot.localMinutes, format)
  const dayName = WEEKDAYS[weekday] ?? ''
  const startsDay = slot.localMinutes < 60
  const description = `${cityName} ${formatClock(slot.localMinutes, format)} ${dayName}, ${STATE_LABEL[state]}`

  return (
    <div
      role="cell"
      data-hour={slot.refHour}
      data-state={state}
      aria-label={description}
      title={description}
      className={cn(
        'relative flex items-center justify-center overflow-hidden leading-none transition-[background-color,color,box-shadow] duration-200 select-none',
        variant === 'row' ? 'h-11 flex-col gap-1 rounded-md lg:h-12 lg:rounded-lg' : 'h-10 gap-1 rounded-lg',
        startsDay &&
          (variant === 'row'
            ? 'before:absolute before:inset-y-2 before:left-0 before:w-[2px] before:rounded-full before:bg-current before:opacity-50'
            : 'before:absolute before:inset-x-2 before:top-0 before:h-[2px] before:rounded-full before:bg-current before:opacity-50'),
        STATE_STYLES[state],
      )}
    >
      <span className={cn('font-mono tracking-tight tabular-nums', variant === 'row' ? 'text-[11px] lg:text-[13px]' : 'text-[13px]')}>
        {hour}
        {minute && <sup className="ml-px text-[0.64em] font-semibold">{minute}</sup>}
      </span>
      <span
        className={cn(
          'min-h-[1em] tracking-wide uppercase',
          variant === 'row' ? 'text-[8px] lg:text-[9px]' : 'text-[10px]',
          startsDay ? 'font-bold' : 'opacity-65',
        )}
      >
        {startsDay ? dayName : period}
      </span>
    </div>
  )
})

