import { HOURS, rangeContains, type HourMask } from '../../domain/schedule'
import { formatRelativeOffset, formatUtcOffset, mod, type TimeFormat } from '../../domain/time'
import type { Schedule, ScheduleRow } from '../../hooks/use-schedule'
import { cn } from '../../lib/cn'
import { useUiStore } from '../../state/ui-store'
import { CityName, RefBadge, RemoveCityButton } from './CityControls'
import { HourCell } from './HourCell'
import { useHourFocus } from './use-hour-focus'

/** Cities as columns, the reference city's 24 hours as rows. */
export function MobileGrid({ schedule }: { schedule: Schedule }) {
  const { rows, analysis, format, referenceWeekday, reference } = schedule
  const focusHandlers = useHourFocus()
  if (!reference) return null

  const columns = `0.75rem repeat(${rows.length}, minmax(0, 1fr))`
  const band = analysis?.mode === 'meeting' ? analysis.mask : null

  return (
    <section aria-label="Hourly availability" className="card overflow-clip px-1.5 pb-1.5">
      <div role="table" aria-label={`Local time in each city, hour by hour through ${reference.timeline.city.name}’s day`}>
        <div
          role="row"
          className="sticky top-0 z-30 -mx-1.5 grid gap-1 border-b border-line bg-surface/90 px-1.5 pt-3 pb-2.5 backdrop-blur-md"
          style={{ gridTemplateColumns: columns }}
        >
          <span aria-hidden />
          {rows.map((row) => (
            <ColumnHeader key={row.timeline.city.id} row={row} />
          ))}
        </div>
        <div className="pt-1.5" {...focusHandlers}>
          {HOURS.map((hour) => (
            <HourRow
              key={hour}
              hour={hour}
              rows={rows}
              columns={columns}
              band={band}
              nowMinutes={reference.nowMinutes}
              format={format}
              referenceWeekday={referenceWeekday}
            />
          ))}
        </div>
      </div>
    </section>
  )
}

function ColumnHeader({ row }: { row: ScheduleRow }) {
  const { timeline, isReference } = row
  const { city, offsetMinutes, diffMinutes } = timeline
  return (
    <div role="columnheader" className="flex min-w-0 flex-col items-center gap-1 text-center">
      <CityName
        city={city}
        isReference={isReference}
        className="w-full text-[13px] leading-tight"
        textClassName="line-clamp-2 min-h-[2lh] wrap-break-word"
      />
      {isReference ? (
        <RefBadge />
      ) : (
        <span className="flex h-[18px] items-center font-mono text-[10.5px] font-medium text-ink-2">
          {formatRelativeOffset(diffMinutes)}
        </span>
      )}
      <span className="font-mono text-[10px] text-ink-3">{formatUtcOffset(offsetMinutes)}</span>
      <RemoveCityButton city={city} className="-mb-1 bg-surface-2/70" />
    </div>
  )
}

interface HourRowProps {
  hour: number
  rows: ScheduleRow[]
  columns: string
  band: HourMask | null
  nowMinutes: number
  format: TimeFormat
  referenceWeekday: number
}

function HourRow({ hour, rows, columns, band, nowMinutes, format, referenceWeekday }: HourRowProps) {
  const focused = useUiStore((s) => s.focus !== null && rangeContains(s.focus, hour))
  const inBand = band?.[hour] ?? false
  const isNow = Math.floor(nowMinutes / 60) === hour

  return (
    <div
      role="row"
      className={cn(
        'relative grid gap-1 py-[2px]',
        inBand && 'bg-overlap/30',
        inBand && !band?.[hour - 1] && 'rounded-t-xl',
        inBand && !band?.[hour + 1] && 'rounded-b-xl',
      )}
      style={{ gridTemplateColumns: columns }}
    >
      <span aria-hidden className="flex items-center justify-center">
        {isNow ? (
          <span className="size-1.5 rounded-full bg-now" />
        ) : (
          hour % 6 === 0 && <span className="h-px w-1.5 rounded-full bg-ink-4" />
        )}
      </span>
      {rows.map(({ timeline, states }) => {
        const slot = timeline.slots[hour]
        if (!slot) return null
        return (
          <HourCell
            key={timeline.city.id}
            variant="column"
