      {isNow && (
        <span
          aria-hidden
          className="pointer-events-none absolute right-0 left-2 z-10 h-[2px] -translate-y-1/2 rounded-full bg-now shadow-[0_0_0_1.5px_var(--surface)]"
          style={{ top: `${((nowMinutes % 60) / 60) * 100}%` }}
        />
      )}
    </div>
  )
}

